<script setup lang="ts">
import { formatDemoTime } from '~/domain/selectors'
import type { ActivityEvent, ComponentId, Completeness, EvidenceView, EvidenceVersion, PackageStatus, ReviewInput, SubmittedPackageRow } from '~/domain/types'

definePageMeta({ layout: 'workspace' })
useHead({ title: 'Pemeriksaan kelengkapan · UKIN PPG UNJ' })
const ukin = useUkin()
const route = useRoute()
const selectedId = computed(() => typeof route.query.id === 'string' ? route.query.id : '')
const search = ref('')
const periodFilter = ref('all')
const statusFilter = ref<Completeness | 'all'>('all')
const formError = ref('')
const success = ref('')
const checks = reactive<Record<ComponentId, boolean>>({ perangkat: false, video: false, studi_kasus: false })
const issues = reactive<Record<ComponentId, string>>({ perangkat: '', video: '', studi_kasus: '' })
const confirmation = ref<HTMLDialogElement | null>(null)
const pendingOutcome = ref<ReviewInput['outcome']>('complete')
const saving = ref(false)
const components: { id: ComponentId; title: string; help: string }[] = [
  { id: 'perangkat', title: 'Perangkat pembelajaran', help: 'Dokumen utama dan lampiran dapat dibuka dan telah diperiksa.' },
  { id: 'video', title: 'Video praktik pembelajaran', help: 'Video wajib dapat diakses dan telah diperiksa secara manual.' },
  { id: 'studi_kasus', title: 'Studi kasus', help: 'Laporan teks atau dokumen dapat dibaca dan telah diperiksa.' },
]
const statusLabels: Record<Completeness, string> = { pending: 'Menunggu pemeriksaan', complete: 'Lengkap secara teknis', needs_correction: 'Perlu perbaikan' }
const packageLabels: Record<PackageStatus, string> = { draft: 'Draf', submitted: 'Terkirim', revision_requested: 'Revisi dibuka', resubmitted: 'Dikirim ulang' }
const actionLabels: Record<string, string> = { draft_saved: 'Draf disimpan', submitted: 'Paket dikirim', resubmitted: 'Paket dikirim ulang', complete: 'Kelengkapan dikonfirmasi', correction_requested: 'Perbaikan diminta', review_complete: 'Kelengkapan dikonfirmasi', review_correction: 'Perbaikan diminta', file_restored: 'File lokal dipulihkan', fixture: 'Contoh skenario' }

const page = computed((): { rows: SubmittedPackageRow[]; detail: EvidenceView | null; versions: EvidenceVersion[]; history: ActivityEvent[]; error: string } => {
  void ukin.snapshot.value
  const actor = ukin.user.value
  if (actor?.role !== 'pengelola') return { rows: [], detail: null, versions: [], history: [], error: 'Halaman pemeriksaan hanya tersedia untuk pengelola demo.' }
  try {
    const rows = ukin.listSubmittedPackages()
    const detail = selectedId.value ? ukin.getEvidence(selectedId.value) : null
    const context = detail ? ukin.getPackage(detail.attempt.id) : null
    return { rows, detail, versions: context?.versions ?? [], history: context?.history ?? [], error: '' }
  } catch (error) { return { rows: [], detail: null, versions: [], history: [], error: error instanceof Error ? error.message : 'Paket belum dapat dibuka.' } }
})
const detail = computed(() => page.value.detail)
const periods = computed(() => [...new Map(page.value.rows.map(row => [row.periodId, { id: row.periodId, name: row.periodName }])).values()])
const rows = computed(() => page.value.rows.filter(row => {
  const query = search.value.trim().toLocaleLowerCase('id-ID')
  return (periodFilter.value === 'all' || row.periodId === periodFilter.value)
    && (statusFilter.value === 'all' || row.completeness === statusFilter.value)
    && (!query || `${row.participantName} ${row.subject}`.toLocaleLowerCase('id-ID').includes(query))
}).sort((a, b) => b.submittedAt.localeCompare(a.submittedAt) || a.participantName.localeCompare(b.participantName)))
const counts = computed(() => ({ pending: page.value.rows.filter(row => row.completeness === 'pending').length, correction: page.value.rows.filter(row => row.completeness === 'needs_correction').length, complete: page.value.rows.filter(row => row.completeness === 'complete').length }))
const reasons = computed(() => components.filter(component => issues[component.id].trim()))
const completeEnabled = computed(() => components.every(component => checks[component.id]) && !reasons.value.length && detail.value?.checklist.every(item => item.complete))
const latestReview = computed(() => detail.value?.reviews.filter(review => review.evidenceVersionId === detail.value?.version.id).at(-1))
const collectionOpen = computed(() => detail.value && Date.parse(ukin.snapshot.value.data.clockNow) >= Date.parse(detail.value.period.collectionOpensAt) && Date.parse(ukin.snapshot.value.data.clockNow) <= Date.parse(detail.value.period.collectionClosesAt))

function resetForm() {
  for (const component of components) { checks[component.id] = false; issues[component.id] = '' }
  formError.value = ''; success.value = ''; confirmation.value?.close()
}
watch([selectedId, () => ukin.user.value?.id], resetForm)
function clearFilters() { search.value = ''; periodFilter.value = 'all'; statusFilter.value = 'all' }
function setQueueStatus(value: Completeness) { search.value = ''; periodFilter.value = 'all'; statusFilter.value = value }
function confirmReview(outcome: ReviewInput['outcome']) {
  formError.value = ''; success.value = ''
  if (!detail.value?.canReview) { formError.value = 'Versi ini tidak dapat diperiksa lagi. Buka paket terkini.'; return }
  if (outcome === 'complete' && !completeEnabled.value) { formError.value = 'Periksa tiga komponen dan pastikan seluruh bukti tersedia sebelum menandai lengkap.'; return }
  if (outcome === 'needs_correction' && !reasons.value.length) { formError.value = 'Tuliskan alasan teknis pada setidaknya satu komponen yang perlu diperbaiki.'; return }
  if (outcome === 'needs_correction') {
    const unexplained = components.filter(component => !checks[component.id] && !issues[component.id].trim())
    if (unexplained.length) { formError.value = `Beri alasan untuk komponen yang belum dapat diperiksa: ${unexplained.map(component => component.title).join(', ')}.`; return }
  }
  pendingOutcome.value = outcome
  confirmation.value?.showModal()
}
function saveReview() {
  if (saving.value || !detail.value) return
  saving.value = true
  try {
    const input: ReviewInput = { outcome: pendingOutcome.value, checks: { ...checks }, issues: {} }
    if (pendingOutcome.value === 'needs_correction') for (const component of reasons.value) input.issues[component.id] = issues[component.id].trim()
    ukin.reviewPackage(detail.value.version.id, input)
    confirmation.value?.close()
    success.value = pendingOutcome.value === 'complete' ? 'Kelengkapan teknis dicatat. Status ini bukan nilai atau keputusan kelulusan.' : 'Permintaan perbaikan dicatat. Peserta dapat menyiapkan revisi dan mengirim versi baru.'
    formError.value = ''
    for (const component of components) { checks[component.id] = false; issues[component.id] = '' }
  } catch (error) { formError.value = error instanceof Error ? error.message : 'Pemeriksaan belum dapat disimpan.' }
  finally { saving.value = false }
}
</script>

<template>
  <div class="review-page">
    <template v-if="page.error"><section class="panel unavailable"><AppIcon name="shield" /><h1>Paket tidak dapat dibuka</h1><p>{{ page.error }}</p><UButton :to="ukin.home.value">Kembali ke ringkasan</UButton><NuxtLink v-if="ukin.user.value?.role === 'pengelola'" to="/app/pemeriksaan" class="text-link">Lihat daftar paket</NuxtLink></section></template>
    <template v-else-if="!detail">
      <header class="page-heading"><p class="eyebrow">RUANG PENGELOLA · KELENGKAPAN</p><h1>Pastikan bukti siap ditinjau<span>.</span></h1><p>Periksa akses dan kelengkapan paket yang telah dikirim. Isi draf peserta tetap berada di ruang peserta.</p></header>
      <div class="queue-summary"><button :class="{ selected: statusFilter === 'pending' }" :aria-pressed="statusFilter === 'pending'" @click="setQueueStatus('pending')"><span>Menunggu pemeriksaan</span><strong>{{ counts.pending }}</strong><AppIcon name="arrow-right" /></button><button :class="{ selected: statusFilter === 'needs_correction' }" :aria-pressed="statusFilter === 'needs_correction'" @click="setQueueStatus('needs_correction')"><span>Perlu perbaikan</span><strong>{{ counts.correction }}</strong><AppIcon name="arrow-right" /></button><button :class="{ selected: statusFilter === 'complete' }" :aria-pressed="statusFilter === 'complete'" @click="setQueueStatus('complete')"><span>Lengkap secara teknis</span><strong>{{ counts.complete }}</strong><AppIcon name="arrow-right" /></button></div>
      <section class="panel queue-panel" aria-labelledby="queue-title"><div class="queue-heading"><div><p class="eyebrow">PAKET TERKIRIM</p><h2 id="queue-title">Antrean pemeriksaan</h2></div><span class="status-badge">{{ page.rows.length }} paket</span></div><div class="filter-row"><label>Cari peserta<input v-model="search" type="search" placeholder="Nama atau bidang studi"></label><label>Periode<select v-model="periodFilter"><option value="all">Semua periode</option><option v-for="period in periods" :key="period.id" :value="period.id">{{ period.name }}</option></select></label><label>Kelengkapan<select v-model="statusFilter"><option value="all">Semua status</option><option value="pending">Menunggu pemeriksaan</option><option value="needs_correction">Perlu perbaikan</option><option value="complete">Lengkap secara teknis</option></select></label></div><p class="result-count" aria-live="polite">{{ rows.length }} dari {{ page.rows.length }} paket ditampilkan</p>
        <div v-if="rows.length" class="table-scroll" tabindex="0" role="region" aria-label="Paket terkirim, dapat digulir mendatar"><table><thead><tr><th scope="col">Peserta</th><th scope="col">Paket</th><th scope="col">Kelengkapan</th><th scope="col"><span class="sr-only">Tindakan</span></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{ row.participantName }}</strong><small>{{ row.subject }}</small><span v-if="row.attemptNumber > 1" class="retaker">Percobaan {{ row.attemptNumber }} · Retaker</span></td><td><strong>Versi {{ row.version }} · {{ packageLabels[row.packageStatus] }}</strong><small>{{ formatDemoTime(row.submittedAt) }}</small><small v-if="row.fixture" class="fixture-note">Bukti contoh bawaan</small></td><td><span class="status-badge" :class="row.completeness">{{ statusLabels[row.completeness] }}</span></td><td><NuxtLink :to="{ path: '/app/pemeriksaan', query: { id: row.id } }" class="text-link">Buka paket <AppIcon name="arrow-right" :size="16" /></NuxtLink></td></tr></tbody></table></div>
        <div v-else class="empty-state"><AppIcon name="file" /><h3>{{ page.rows.length ? 'Belum ada paket yang cocok.' : 'Belum ada paket terkirim.' }}</h3><p>{{ page.rows.length ? 'Ubah pencarian atau tampilkan seluruh status.' : 'Paket muncul setelah peserta menyelesaikan pengiriman final.' }}</p><UButton v-if="page.rows.length" variant="soft" @click="clearFilters">Tampilkan semua paket</UButton></div>
      </section><p class="scope-note"><AppIcon name="help" /> Lengkap adalah status administratif. Pemeriksaan ini tidak menghasilkan skor atau keputusan kelulusan.</p>
    </template>
    <template v-else>
      <NuxtLink to="/app/pemeriksaan" class="text-link back-link"><AppIcon name="arrow-left" :size="17" /> Semua paket terkirim</NuxtLink>
      <header class="page-heading detail-heading"><p class="eyebrow">PEMERIKSAAN PAKET · VERSI {{ detail.version.version }}</p><h1>{{ detail.participant.displayName }}</h1><p>{{ detail.attempt.subject }} · Percobaan {{ detail.attempt.attemptNumber }}</p></header>
      <section class="package-summary"><div><span>Periode</span><strong>{{ detail.period.name }}</strong></div><div><span>Bukti pengiriman</span><strong>{{ detail.version.receipt }}</strong><small>{{ formatDemoTime(detail.version.submittedAt) }}</small></div><div><span>Status paket saat ini</span><strong>{{ packageLabels[detail.attempt.packageStatus] }}</strong><span class="status-badge" :class="detail.attempt.completeness">{{ statusLabels[detail.attempt.completeness] }}</span></div></section>
      <AttemptHistory :attempts="detail.attemptHistory" :current-attempt-id="detail.attempt.id" />
      <p v-if="detail.version.fixture" class="notice">Paket ini merupakan contoh bawaan fiktif untuk demonstrasi. Riwayat yang berlabel contoh bukan tindakan pengguna pada sesi ini.</p>
      <p v-if="!detail.isCurrent" class="notice archive-notice">Anda membuka arsip versi {{ detail.version.version }}. Pemeriksaan baru hanya dapat dicatat pada versi terkini.</p>
      <p v-if="!collectionOpen" class="notice archive-notice">Jendela pengumpulan peserta telah ditutup menurut jam demo. Pemeriksaan teknis tetap tersedia; peserta perlu jendela aktif untuk mengirim revisi.</p>
      <p v-if="success" class="notice" role="status">{{ success }}</p>
      <div class="review-columns"><EvidenceReadView :content="detail.version.content" /><aside class="review-sidebar">
        <section class="panel inspection-panel" aria-labelledby="inspection-title"><p class="eyebrow">TINJAU SECARA MANUAL</p><h2 id="inspection-title">Catat kelengkapan</h2><p class="panel-intro">Buka bukti sebelum mencentang. Format tautan valid atau pemutar termuat belum berarti bukti telah diperiksa.</p>
          <template v-if="detail.canReview"><div v-for="component in components" :key="component.id" class="review-component"><label class="check-row"><input v-model="checks[component.id]" type="checkbox"><span><strong>{{ component.title }}</strong><small>{{ component.help }}</small></span></label><label class="reason-field" :for="`issue-${component.id}`">Alasan perbaikan teknis <span>(jika perlu)</span></label><textarea :id="`issue-${component.id}`" v-model="issues[component.id]" rows="3" maxlength="2000" placeholder="Jelaskan kendala dan perbaikan yang diperlukan." /></div>
            <div v-if="detail.checklist.some(item => !item.complete)" class="checklist-warning"><strong>Bukti belum lengkap atau tersedia</strong><ul><template v-for="item in detail.checklist" :key="item.id"><li v-for="issue in item.issues" :key="issue">{{ issue }}</li></template></ul></div>
            <p v-if="formError && !confirmation?.open" class="form-error" role="alert">{{ formError }}</p><div class="review-actions"><UButton block :disabled="saving || !completeEnabled" @click="confirmReview('complete')">Tandai lengkap</UButton><UButton block variant="outline" :disabled="saving" @click="confirmReview('needs_correction')">Minta perbaikan teknis</UButton></div><p class="review-footnote">Penandaan lengkap memerlukan tiga konfirmasi, bukti tersedia, dan tanpa alasan perbaikan. Setiap komponen yang belum dapat diperiksa memerlukan alasan. Batas teknis demo: 2.000 karakter per alasan.</p>
          </template>
          <div v-else class="read-only-message"><AppIcon name="shield" /><strong>{{ detail.attempt.packageStatus === 'revision_requested' && detail.isCurrent ? 'Menunggu revisi peserta' : 'Versi ini hanya dapat dibaca' }}</strong><p>{{ detail.attempt.packageStatus === 'revision_requested' && detail.isCurrent ? 'Peserta mendapat draf revisi. Pengiriman ulang akan menghasilkan versi dan bukti pengiriman baru.' : 'Buka versi terkini untuk melihat tindakan yang tersedia.' }}</p></div>
        </section>
        <section v-if="latestReview" class="panel prior-review"><p class="eyebrow">PEMERIKSAAN PADA VERSI INI</p><h2>{{ latestReview.outcome === 'complete' ? 'Lengkap secara teknis' : 'Perbaikan diminta' }}</h2><p>{{ latestReview.actorName }} · {{ formatDemoTime(latestReview.reviewedAt) }}</p><span v-if="latestReview.fixture" class="status-badge">Contoh bawaan</span><dl v-if="latestReview.outcome === 'needs_correction'"><template v-for="component in components" :key="component.id"><template v-if="latestReview.issues[component.id]"><dt>{{ component.title }}</dt><dd>{{ latestReview.issues[component.id] }}</dd></template></template></dl></section>
        <section class="panel version-panel"><p class="eyebrow">JEJAK PAKET</p><h2>Versi bukti</h2><NuxtLink v-for="version in [...page.versions].reverse()" :key="version.id" :to="{ path: '/app/pemeriksaan', query: { id: version.id } }" :class="{ current: version.id === detail.version.id }"><span><strong>Versi {{ version.version }}</strong><small>{{ formatDemoTime(version.submittedAt) }}</small></span><AppIcon :name="version.id === detail.version.id ? 'check' : 'arrow-right'" :size="16" /></NuxtLink></section>
      </aside></div>
      <section class="panel history-panel" aria-labelledby="history-title"><div class="queue-heading"><div><p class="eyebrow">AKTOR DAN WAKTU DEMO</p><h2 id="history-title">Riwayat paket</h2></div><AppIcon name="clock" /></div><ol v-if="page.history.length" class="history-list"><li v-for="event in [...page.history].reverse()" :key="event.id"><span class="history-dot" /><div><strong>{{ actionLabels[event.action] || event.action }}</strong><p v-if="event.reason">{{ event.reason }}</p><small>{{ event.actorName }} · {{ formatDemoTime(event.at) }}<span v-if="event.fixture"> · Contoh bawaan</span></small></div></li></ol><p v-else class="muted">Belum ada aktivitas pada paket ini.</p></section>
    </template>
    <dialog ref="confirmation" class="review-dialog" aria-labelledby="review-confirm-title"><p class="eyebrow">KONFIRMASI PEMERIKSAAN</p><h2 id="review-confirm-title">{{ pendingOutcome === 'complete' ? 'Tandai paket lengkap?' : 'Buka perbaikan untuk peserta?' }}</h2><p v-if="pendingOutcome === 'complete'">Anda menyatakan telah memeriksa akses dan kelengkapan tiga komponen versi {{ detail?.version.version }}. Status ini tidak berarti kompeten atau lulus.</p><template v-else><p>Peserta dapat memperbaiki draf dan mengirim versi baru. Versi ini tetap menjadi arsip. Hasil atau penugasan versi lama tidak berlaku untuk bukti baru.</p><ul><li v-for="component in reasons" :key="component.id"><strong>{{ component.title }}:</strong> {{ issues[component.id] }}</li></ul></template><p v-if="formError" class="form-error" role="alert">{{ formError }}</p><div class="dialog-actions"><UButton color="neutral" variant="outline" autofocus :disabled="saving" @click="confirmation?.close()">Batal</UButton><UButton :disabled="saving" @click="saveReview">{{ pendingOutcome === 'complete' ? 'Ya, tandai lengkap' : 'Ya, minta perbaikan' }}</UButton></div></dialog>
  </div>
</template>

<style scoped>
