lor:var(--brand-dark);font-size:12px}.status-badge.pending{background:var(--canvas);color:var(--muted)}.status-badge.needs_correction{background:#fff1e1;color:var(--warning)}.scope-note{display:flex;gap:9px;align-items:flex-start;color:var(--muted);font-size:13px;line-height:1.7}.scope-note svg{margin-top:2px;flex-basis:18px}.empty-state{text-align:center;padding:42px 20px}.empty-state>svg{margin:auto;color:var(--brand);width:32px;height:32px}.empty-state h3{font-size:20px;font-weight:700;margin:17px 0 10px}.empty-state p{color:var(--muted);font-size:14px;margin-bottom:20px}.back-link{font-size:13px;justify-self:start}.detail-heading h1{font-size:34px}.package-summary{display:grid;grid-template-columns:1.3fr 1.2fr 1fr;gap:20px;padding:24px 28px;background:var(--brand-deep);border-radius:16px;color:white}.package-summary>div{display:grid;gap:7px;align-content:start}.package-summary>div>span:first-child{color:#bde3d9;font-size:12px}.package-summary strong{font-size:14px;line-height:1.6;overflow-wrap:anywhere}.package-summary small{color:#c8e3dd;font-size:12px}.package-summary .status-badge{justify-self:start;margin-top:3px}.archive-notice{background:#fff8ed;border-color:#e6d0ad;color:var(--warning)}.review-columns{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(300px,1fr);gap:24px;align-items:start}.review-sidebar{display:grid;gap:22px;min-width:0}.inspection-panel,.prior-review,.version-panel{padding:26px}.inspection-panel>.eyebrow,.prior-review>.eyebrow,.version-panel>.eyebrow{margin-bottom:10px}.panel-intro{font-size:13px;line-height:1.8;color:var(--muted);margin-top:14px}.review-component{padding-top:22px;margin-top:22px;border-top:1px solid var(--line)}.check-row{display:flex;gap:11px;align-items:flex-start;cursor:pointer}.check-row input{width:18px;height:18px;flex:0 0 18px;accent-color:var(--brand);margin-top:3px}.check-row strong{display:block;font-size:14px;line-height:1.5}.check-row small{display:block;font-size:12px;line-height:1.7;color:var(--mu